func:
// Devices alert banner. Two feeds arrive here:
//  - control results ('OK (200)', 'ERROR ...', 'Set HUBITAT_...' when
//    config is missing) from Format result / Build Maker API call;
//  - the 300s list poll from Format device list: a device COUNT
//    (number) on success, 'ERROR ...' when the hub is unreachable.
var p = String(msg.payload || '');
var sev = 'ok';
var text;
if (typeof msg.payload === 'number') {
  // list poll succeeded: N devices reachable = hub is up
  text = msg.payload + ' devices reachable';
} else if (p.indexOf('ERROR') === 0) {
  sev = 'critical';
  text = p.slice(0, 120);
} else if (p.indexOf('Set HUBITAT') === 0) {
  sev = 'warning';
  text = 'Hubitat config missing: set HUBITAT_APP_ID / ACCESS_TOKEN / DEVICE_ID';
} else if (p.indexOf('OK') === 0) {
  text = 'Hubitat control OK';
} else {
  sev = 'info';
  text = p || 'Awaiting first result';
}
node.status({fill: sev === 'ok' ? 'green' : (sev === 'critical' ? 'red' : 'yellow'), shape: 'dot', text: sev});
msg.payload = {severity: sev, message: text};
return msg;

var base = env.get('HUBITAT_URL') || '';
var app  = env.get('HUBITAT_APP_ID') || '';
var tok  = env.get('HUBITAT_ACCESS_TOKEN') || env.get('HUBITAT_API_KEY') || '';
if (!base || !app || !tok) {
  node.status({fill:'red',shape:'ring',text:'missing config'});
  msg.payload = [];
  return [null, msg];
}
msg.method = 'GET';
msg.url = base.replace(/\/+$/, '') + '/apps/api/' + app + '/devices?access_token=' + tok;
node.status({fill:'blue',shape:'dot',text:'listing'});
return [msg, null];

var body = msg.payload;
if (msg.error || !msg.statusCode) {
  node.status({fill:'red',shape:'ring',text:'unreachable'});
  msg.payload = [];
  // out1 feeds Device Count AND the alert evaluator: an explicit
  // ERROR string makes the banner critical ('hub unreachable'),
  // which a count of 0 cannot distinguish from 'no devices'.
  var e = {payload: 'ERROR: Hubitat unreachable (' + (msg.error || 'no response') + ')'};
  return [msg, e];
}
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = []; }
}
var list = Array.isArray(body) ? body : (body && body.devices) || [];
node.status({fill:'green',shape:'dot',text:list.length + ' devices'});
msg.payload = list;
var c = {payload: list.length};
return [msg, c];

// Hubitat Maker API: GET /apps/api/<appId>/devices/<devId>/<cmd>/<value>?access_token=<tok>
var base = env.get('HUBITAT_URL') || 'http://hubitat.local';
var app  = env.get('HUBITAT_APP_ID') || '';
var tok  = env.get('HUBITAT_ACCESS_TOKEN') || env.get('HUBITAT_API_KEY') || '';
var dev  = env.get('HUBITAT_DEVICE_ID') || '';
if (!app || !tok || !dev) {
  node.status({fill:'red',shape:'ring',text:'missing config'});
  msg.payload = 'Set HUBITAT_APP_ID, HUBITAT_ACCESS_TOKEN and HUBITAT_DEVICE_ID in the LXC env';
  return [null, msg];
}
var cmd, val = null;
if (msg.topic === 'hubitat/power') { cmd = msg.payload ? 'on' : 'off'; }
else if (msg.topic === 'hubitat/level') { cmd = 'setLevel'; val = msg.payload; }
else { node.status({fill:'grey',shape:'ring',text:'ignored'}); return null; }
var url = base.replace(/\/+$/, '') + '/apps/api/' + app + '/devices/' + dev + '/' + cmd;
if (val !== null) { url += '/' + val; }
url += '?access_token=' + tok;
msg.method = 'GET';
msg.url = url;
node.status({fill:'blue',shape:'dot',text:cmd});
return [msg, null];

// http request sets msg.error on a transport failure.
if (msg.error || !msg.statusCode) {
  node.status({fill:'red',shape:'ring',text:'unreachable'});
  msg.payload = 'ERROR: Hubitat unreachable (' + (msg.error || msg.payload || 'no response') + ')';
  return [msg, msg];
}
if (msg.statusCode >= 200 && msg.statusCode < 300) {
  node.status({fill:'green',shape:'dot',text:'ok'});
  msg.payload = 'OK (' + msg.statusCode + ')';
} else {
  node.status({fill:'red',shape:'ring',text:'http ' + msg.statusCode});
  var body = (typeof msg.payload === 'string') ? msg.payload : JSON.stringify(msg.payload);
  msg.payload = 'ERROR HTTP ' + msg.statusCode + ': ' + String(body).slice(0, 200);
}
return [msg, msg];
